-- LF M4, 112 fuentes inventariadas, 8 candidatas; ninguna regla publicada ni deprecada.
-- Fuente fichas: sandbox/lf_contract_gate_test/nucleo_ci/m2l2_7_candidatas_v1.json
BEGIN;
DO $m4$
DECLARE f jsonb; p jsonb; dry jsonb; applied jsonb; eval jsonb; t jsonb; truth jsonb; bad jsonb; mutant_truth jsonb;
 code text; ref_id integer; n integer:=0; cases integer; total_tests integer:=0; actual_sources integer;
 oldlegacy jsonb; oldrules jsonb; oldversions jsonb; olddeprec jsonb; oldapps jsonb; oldeffective jsonb; oldekb integer;
BEGIN
 SELECT count(*) INTO actual_sources FROM lf_ops.nucleo_regla_familia f
 JOIN lf_ops.v_reglas_compat_v1 v ON v.id=f.regla_id WHERE f.familia='OFFERS_INSTALLMENTS';
 IF actual_sources<>53 OR EXISTS (SELECT 1 FROM lf_ops.nucleo_reglas WHERE codigo LIKE 'M2L2-C0%') THEN RAISE EXCEPTION 'M2L2_SOURCE_OR_ID_DRIFT %',actual_sources; END IF;
 SELECT jsonb_agg(to_jsonb(r) ORDER BY id) INTO oldlegacy FROM lf_ops.reglas r;
 SELECT jsonb_agg(to_jsonb(r) ORDER BY codigo) INTO oldrules FROM lf_ops.nucleo_reglas r;
 SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,version) INTO oldversions FROM lf_ops.nucleo_regla_versiones r;
 SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,version) INTO olddeprec FROM lf_ops.nucleo_deprecaciones r;
 SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,nodo) INTO oldapps FROM lf_ops.nucleo_aplicaciones r;
 SELECT jsonb_agg(jsonb_build_object('nodo',nd.codigo,'r',to_jsonb(e)) ORDER BY nd.codigo,e.regla)
 INTO oldeffective FROM lf_ops.nucleo_nodos nd CROSS JOIN LATERAL lf_ops.nucleo_reglas_efectivas_v1(nd.codigo,now()) e;
 SELECT count(*) INTO oldekb FROM public.lf_error_knowledge;
 FOR f IN SELECT value FROM jsonb_array_elements('[{"codigo":"m2l2_intento_materializar_ofertas","familia":"OFFERS_INSTALLMENTS","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m2l2_modalidades_duplican_deuda_como_ofertas","familia":"OFFERS_INSTALLMENTS","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m2l2_intento_mostrar_ver_mas_planes","familia":"OFFERS_INSTALLMENTS","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m2l2_sin_planes_adicionales_autorizados","familia":"OFFERS_INSTALLMENTS","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m2l2_intento_render_card_oferta","familia":"OFFERS_INSTALLMENTS","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m2l2_card_estado_visual_incongruente","familia":"OFFERS_INSTALLMENTS","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m2l2_intento_render_copy_ofertas","familia":"OFFERS_INSTALLMENTS","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m2l2_copy_incongruente_con_seleccion","familia":"OFFERS_INSTALLMENTS","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m2l2_intento_cerrar_modal_cuotas","familia":"OFFERS_INSTALLMENTS","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m2l2_modal_cierre_pierde_seleccion_o_navega","familia":"OFFERS_INSTALLMENTS","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m2l2_intento_render_plan_modal","familia":"OFFERS_INSTALLMENTS","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m2l2_primera_cuota_no_destacada_o_ausente","familia":"OFFERS_INSTALLMENTS","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m2l2_intento_mostrar_cta_oferta_home","familia":"OFFERS_INSTALLMENTS","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m2l2_copy_promete_simulacion_o_oferta_no_real","familia":"OFFERS_INSTALLMENTS","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"}]'::jsonb) LOOP
  code:=f->>'codigo';
  IF EXISTS (SELECT 1 FROM lf_ops.nucleo_hechos WHERE codigo=code) THEN RAISE EXCEPTION 'M2L2_FACT_COLLISION %',code; END IF;
  INSERT INTO lf_ops.nucleo_hechos(codigo,tipo_dato,unidad,descripcion) VALUES (code,'boolean','ninguna','Hecho lógico M4 seguridad, fuente backend/cliente y binding Paulo pendientes; tabla_ref y columna_ref NULL');
  INSERT INTO lf_ops.nucleo_familia_vocabulario(familia,hecho,origen) VALUES(f->>'familia',code,'CURADO');
 END LOOP;
 FOR p IN SELECT value FROM jsonb_array_elements('[{"tipo":"NUEVA","codigo":"M2L2-C01","clave":"m2l2_g05","titulo":"Una oferta por deuda con modalidades alternativas","descripcion":"Al materializar ofertas de un cliente, BLOQUEAR que pago único y cuotas de una misma deuda sean creados o presentados como ofertas independientes; cada oferta representa una deuda independiente y sus modalidades comparten identidad de oferta. No valida montos ni inventa vínculo físico deuda/oferta; fuente de Paulo pendiente.","familia":"OFFERS_INSTALLMENTS","naturaleza":"CONDUCTA","autoridad":"LEG-PRODUCTO","dueno":"PRODUCTO","alcance":"CLIENT_HOME","modo":"HEREDA","clase":"PANTALLA","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m2l2_intento_materializar_ofertas"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"m2l2_modalidades_duplican_deuda_como_ofertas"},"der":{"lit":true}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/146,147","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m2l2_intento_materializar_ofertas":true,"m2l2_modalidades_duplican_deuda_como_ofertas":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m2l2_intento_materializar_ofertas":true,"m2l2_modalidades_duplican_deuda_como_ofertas":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m2l2_intento_materializar_ofertas":false,"m2l2_modalidades_duplican_deuda_como_ofertas":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m2l2_intento_materializar_ofertas":false,"m2l2_modalidades_duplican_deuda_como_ofertas":false},"esperado":false}]},{"tipo":"NUEVA","codigo":"M2L2-C02","clave":"m2l2_g09","titulo":"Ver más planes solo con adicionales autorizados","descripcion":"En presentación de planes de cuotas, BLOQUEAR el enlace Ver más planes si la lista autoritativa no contiene planes adicionales fuera del conjunto inicial. No asumir cardinalidad ni configurar plan ficticio; fuente de disponibilidad Paulo pendiente.","familia":"OFFERS_INSTALLMENTS","naturaleza":"CONDUCTA","autoridad":"LEG-PRODUCTO","dueno":"PRODUCTO","alcance":"CLIENT_HOME","modo":"HEREDA","clase":"PANTALLA","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m2l2_intento_mostrar_ver_mas_planes"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"m2l2_sin_planes_adicionales_autorizados"},"der":{"lit":true}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/157","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m2l2_intento_mostrar_ver_mas_planes":true,"m2l2_sin_planes_adicionales_autorizados":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m2l2_intento_mostrar_ver_mas_planes":true,"m2l2_sin_planes_adicionales_autorizados":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m2l2_intento_mostrar_ver_mas_planes":false,"m2l2_sin_planes_adicionales_autorizados":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m2l2_intento_mostrar_ver_mas_planes":false,"m2l2_sin_planes_adicionales_autorizados":false},"esperado":false}]},{"tipo":"NUEVA","codigo":"M2L2-C03","clave":"m2l2_g13","titulo":"Card de oferta refleja el estado autorizado","descripcion":"En render de card de oferta, BLOQUEAR presentación visual incongruente con estado server-side: sin selección sin borde activo, seleccionada con modalidad y ahorro visibles cuando corresponde, vencida con opciones deshabilitadas, borde gris y badge Oferta vencida. No impone estilo en otras cards y estado efectivo proviene de Paulo.","familia":"OFFERS_INSTALLMENTS","naturaleza":"CONDUCTA","autoridad":"LEG-PRODUCTO","dueno":"PRODUCTO","alcance":"CLIENT_HOME","modo":"HEREDA","clase":"PANTALLA","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m2l2_intento_render_card_oferta"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"m2l2_card_estado_visual_incongruente"},"der":{"lit":true}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/171","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m2l2_intento_render_card_oferta":true,"m2l2_card_estado_visual_incongruente":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m2l2_intento_render_card_oferta":true,"m2l2_card_estado_visual_incongruente":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m2l2_intento_render_card_oferta":false,"m2l2_card_estado_visual_incongruente":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m2l2_intento_render_card_oferta":false,"m2l2_card_estado_visual_incongruente":false},"esperado":false}]},{"tipo":"NUEVA","codigo":"M2L2-C04","clave":"m2l2_g14","titulo":"Copy de ofertas pendientes según selección","descripcion":"Al mostrar CTA Continuar en pantalla multi oferta, BLOQUEAR si existen ofertas sin seleccionar y falta o se altera el texto aprobado Podrás configurar las demás ofertas después.; si todas están elegidas, BLOQUEAR el copy sobrante. El hecho de incongruencia se deriva del estado de selección y del texto renderizado, sin binding inventado.","familia":"OFFERS_INSTALLMENTS","naturaleza":"CONDUCTA","autoridad":"LEG-PRODUCTO","dueno":"PRODUCTO","alcance":"CLIENT_HOME","modo":"HEREDA","clase":"PANTALLA","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m2l2_intento_render_copy_ofertas"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"m2l2_copy_incongruente_con_seleccion"},"der":{"lit":true}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/172","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m2l2_intento_render_copy_ofertas":true,"m2l2_copy_incongruente_con_seleccion":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m2l2_intento_render_copy_ofertas":true,"m2l2_copy_incongruente_con_seleccion":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m2l2_intento_render_copy_ofertas":false,"m2l2_copy_incongruente_con_seleccion":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m2l2_intento_render_copy_ofertas":false,"m2l2_copy_incongruente_con_seleccion":false},"esperado":false}]},{"tipo":"NUEVA","codigo":"M2L2-C05","clave":"m2l2_g16","titulo":"Cerrar modal de planes conserva selección anterior","descripcion":"Al cerrar por X o Cancelar el modal de cuotas, BLOQUEAR el cambio involuntario de navegación o la pérdida de selecciones anteriores en pantalla multi oferta. No convierte Cancelar en confirmación de nuevo plan ni afecta otros modales.","familia":"OFFERS_INSTALLMENTS","naturaleza":"CONDUCTA","autoridad":"LEG-PRODUCTO","dueno":"PRODUCTO","alcance":"CLIENT_HOME","modo":"HEREDA","clase":"PANTALLA","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m2l2_intento_cerrar_modal_cuotas"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"m2l2_modal_cierre_pierde_seleccion_o_navega"},"der":{"lit":true}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/238","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m2l2_intento_cerrar_modal_cuotas":true,"m2l2_modal_cierre_pierde_seleccion_o_navega":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m2l2_intento_cerrar_modal_cuotas":true,"m2l2_modal_cierre_pierde_seleccion_o_navega":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m2l2_intento_cerrar_modal_cuotas":false,"m2l2_modal_cierre_pierde_seleccion_o_navega":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m2l2_intento_cerrar_modal_cuotas":false,"m2l2_modal_cierre_pierde_seleccion_o_navega":false},"esperado":false}]},{"tipo":"NUEVA","codigo":"M2L2-C06","clave":"m2l2_g18","titulo":"Primera cuota a pagar hoy destacada por plan","descripcion":"En render de cada plan dentro del modal de cuotas, BLOQUEAR cuando la primera cuota a pagar hoy no aparece visible y con jerarquía destacada sobre el total. El importe exacto se obtiene de plan backend autorizado por Paulo; no inferir fórmula ni precio.","familia":"OFFERS_INSTALLMENTS","naturaleza":"CONDUCTA","autoridad":"LEG-PRODUCTO","dueno":"PRODUCTO","alcance":"CLIENT_HOME","modo":"HEREDA","clase":"PANTALLA","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m2l2_intento_render_plan_modal"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"m2l2_primera_cuota_no_destacada_o_ausente"},"der":{"lit":true}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/244","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m2l2_intento_render_plan_modal":true,"m2l2_primera_cuota_no_destacada_o_ausente":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m2l2_intento_render_plan_modal":true,"m2l2_primera_cuota_no_destacada_o_ausente":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m2l2_intento_render_plan_modal":false,"m2l2_primera_cuota_no_destacada_o_ausente":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m2l2_intento_render_plan_modal":false,"m2l2_primera_cuota_no_destacada_o_ausente":false},"esperado":false}]},{"tipo":"NUEVA","codigo":"M2L2-C07","clave":"m2l2_g25","titulo":"Home no presenta estimación hipotética como oferta","descripcion":"Solo al mostrar el CTA de oferta en Home, BLOQUEAR el copy que prometa simulación referencial u oferta inexistente. Mantener texto aprobado Revisar tu oferta, si la tenemos disponible y resultado binario con oferta real autorizada o sin oferta; validación comercial efectiva pendiente Paulo.","familia":"OFFERS_INSTALLMENTS","naturaleza":"CONDUCTA","autoridad":"LEG-PRODUCTO","dueno":"PRODUCTO","alcance":"CLIENT_HOME","modo":"HEREDA","clase":"PANTALLA","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m2l2_intento_mostrar_cta_oferta_home"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"m2l2_copy_promete_simulacion_o_oferta_no_real"},"der":{"lit":true}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/382","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m2l2_intento_mostrar_cta_oferta_home":true,"m2l2_copy_promete_simulacion_o_oferta_no_real":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m2l2_intento_mostrar_cta_oferta_home":true,"m2l2_copy_promete_simulacion_o_oferta_no_real":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m2l2_intento_mostrar_cta_oferta_home":false,"m2l2_copy_promete_simulacion_o_oferta_no_real":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m2l2_intento_mostrar_cta_oferta_home":false,"m2l2_copy_promete_simulacion_o_oferta_no_real":false},"esperado":false}]}]'::jsonb) LOOP
  code:=p->>'codigo';
  FOR ref_id IN SELECT unnest(string_to_array(split_part(p->'origen'->>'ref','/',2),','))::integer LOOP
   IF NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_familia f JOIN lf_ops.v_reglas_compat_v1 v ON v.id=f.regla_id WHERE f.familia='OFFERS_INSTALLMENTS' AND v.id=ref_id)
   THEN RAISE EXCEPTION 'M2L2_LEGACY_NOT_FOUND % %',code,ref_id; END IF;
  END LOOP;
  dry:=lf_ops.nucleo_regla_proponer_v1(p,false);
  IF dry->>'resultado'<>'EVALUADA_SIN_ESCRIBIR' OR (dry->>'bloqueantes')::integer<>0 THEN RAISE EXCEPTION 'M2L2_PREFLIGHT % %',code,dry; END IF;
  cases:=0;
  FOR t IN SELECT value FROM jsonb_array_elements(p->'pruebas') LOOP
    truth:=lf_ops.nucleo_eval_v1(p->'condicion',t->'entrada');
    IF truth IS DISTINCT FROM t->'esperado' THEN RAISE EXCEPTION 'M2L2_WRONG_CONTROL % case=% expected=% actual=%',code,cases,t->'esperado',truth; END IF;
    cases:=cases+1;
  END LOOP;
  IF cases<>4 THEN RAISE EXCEPTION 'M2L2_CASE_COVERAGE %',code; END IF;
  SELECT value INTO bad FROM jsonb_array_elements(p->'pruebas') WITH ORDINALITY x(value,ord) WHERE ord=3;
  IF bad->'esperado' IS DISTINCT FROM 'false'::jsonb THEN RAISE EXCEPTION 'M2L2_MUTANT_NEGATIVE_CASE_MISSING %',code; END IF;
  -- Remove scope guard (left operand): must activate erroneously on the scope-inactive test.
  mutant_truth:=lf_ops.nucleo_eval_v1(p->'condicion'->'der',bad->'entrada');
  IF mutant_truth IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'M2L2_GUARD_MUTANT_SURVIVED % %',code,mutant_truth; END IF;
  RAISE NOTICE 'M2L2_CASES % count=% guard_mutant_detected=true',code,cases;
  applied:=lf_ops.nucleo_regla_proponer_v1(p,true);
  IF applied->>'resultado'<>'CANDIDATA' OR applied->>'version'<>'1' THEN RAISE EXCEPTION 'M2L2_DOOR_REJECTED % %',code,applied; END IF;
  eval:=lf_ops.nucleo_regla_evaluar_v1(code,true);
  IF eval->>'decision'<>'BLOQUEADA' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(eval->'motivos') m WHERE m->>'dimension'='JUICIO') THEN RAISE EXCEPTION 'M2L2_UNJUDGED_MUST_BLOCK % %',code,eval; END IF;
  IF NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_reglas r JOIN lf_ops.nucleo_regla_versiones v ON v.regla=r.codigo WHERE r.codigo=code AND r.estado='CANDIDATA' AND r.regla_legacy_id IS NULL AND v.version=1 AND v.estado='CANDIDATA' AND v.publicada_desde IS NULL AND v.exigible_desde IS NULL)
  THEN RAISE EXCEPTION 'M2L2_NOT_CANDIDATE_ONLY %',code; END IF;
  RAISE NOTICE 'M2L2_CANDIDATE %',jsonb_build_object('code',code,'cases',cases,'decision',eval->>'decision','hash',lf_ops.nucleo_hash_paquete_v1(code,1),'estado','CANDIDATA');
  n:=n+1;total_tests:=total_tests+cases;
 END LOOP;
 IF EXISTS(SELECT 1 FROM public.lf_error_knowledge WHERE codigo='LF-NUCLEO-M2L2-UI-SEMANTIC-BINDINGS-PENDING-20261123-001') THEN RAISE EXCEPTION 'M2L2_EKB_DUPLICATE'; END IF;
 INSERT INTO public.lf_error_knowledge(codigo,categoria,titulo,descripcion,causa_raiz,patron,prevencion,validacion,severidad,frecuencia,primera_vez,ultima_vez,lote_origen,estado,evidencia)
 VALUES('LF-NUCLEO-M2L2-UI-SEMANTIC-BINDINGS-PENDING-20261123-001','NUCLEO_REGLAS','M2L2 obligaciones UI de ofertas pendientes de binding','Siete obligaciones UI M2L2 con hechos booleanos sintéticos; falta binding runtime/juicio independiente, no se acredita UI real.','Migración de textos antes de binding físico con fuente verificable','M2L2_UI_SEMANTIC_BINDINGS_PENDING','Exigir binding acreditado de Paulo, señal de intento real, tests de integración y juicio independiente antes de publicar.','7 candidatas; 28 casos; 7 mutantes; PG17 BEGIN/ROLLBACK; no publicar','HIGH',1,now(),now(),'M2L2-OFFERS-INSTALLMENTS-20261123','ACTIVO','docs/nucleo/LF_M2_LOTE2_SIETE_GRUPOS_20261123.md; sandbox/lf_contract_gate_test/nucleo_ci/m2l2_7_candidatas_v1.json');
 IF n<>7 OR total_tests<>28 OR (SELECT count(*) FROM public.lf_error_knowledge)<>oldekb+1
 OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY id) FROM lf_ops.reglas r) IS DISTINCT FROM oldlegacy
 OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY codigo) FROM lf_ops.nucleo_reglas r WHERE codigo NOT LIKE 'M2L2-C0%') IS DISTINCT FROM oldrules
 OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,version) FROM lf_ops.nucleo_regla_versiones r WHERE regla NOT LIKE 'M2L2-C0%') IS DISTINCT FROM oldversions
 OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones r) IS DISTINCT FROM olddeprec
 OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,nodo) FROM lf_ops.nucleo_aplicaciones r WHERE regla NOT LIKE 'M2L2-C0%') IS DISTINCT FROM oldapps
 OR (SELECT jsonb_agg(jsonb_build_object('nodo',nd.codigo,'r',to_jsonb(e)) ORDER BY nd.codigo,e.regla) FROM lf_ops.nucleo_nodos nd CROSS JOIN LATERAL lf_ops.nucleo_reglas_efectivas_v1(nd.codigo,now()) e) IS DISTINCT FROM oldeffective
 OR (SELECT estado FROM lf_ops.nucleo_reglas WHERE codigo='REG_CHK_007')<>'CANDIDATA'
 THEN RAISE EXCEPTION 'M2L2_UNAUTHORIZED_DRIFT count=% tests=%',n,total_tests; END IF;
 RAISE NOTICE 'M2L2_PASS 7/7 candidate-only; 28/28 scoped cases; 7 guard mutants; legacy unchanged; zero deprecations';
END $m4$;
COMMIT;
